import { zeroSteps, zeroSources } from './zero.js';
import { renderLessonDemo } from './lesson-demo.js';
import { t as ui } from './i18n.js';

export function plainFlow(items, escape) {
  return `<ol class="plain-flow">${items.map(([title,detail],i)=>`<li><span class="flow-order">${i+1}</span><strong>${escape(title)}</strong><span>${escape(detail)}</span></li>`).join('')}</ol>`;
}

function termCards(terms, inline, escape) {
  return `<dl class="term-cards">${terms.map(t=>`<div><dt>${escape(t.term)}</dt><dd>${inline(t.meaning)}</dd></div>`).join('')}</dl>`;
}

export function renderChapterBridge(c, {inline,escape}) {
  if (!c.bridge) return '';
  const b=c.bridge;
  return `${renderLessonDemo('chapter',c.id)}<section class="chapter-bridge" id="chapter-bridge"><div class="eyebrow">${ui('先接上前一步，再学新东西','Connect the previous step before learning something new')}</div><p><b>${ui('你已经知道：','You already know:')}</b>${inline(b.known)}</p><p><b>${ui('接着遇到的问题：','The next problem:')}</b>${inline(b.problem)}</p><p><b>${ui('本章的办法：','This chapter’s approach:')}</b>${inline(b.idea)}</p><h2>${ui('这章先认识这几个词','Start with these terms')}</h2>${termCards(b.terms,inline,escape)}<p class="takeaway">${inline(b.takeaway)}</p></section>`;
}

export function renderZeroPage(stepId, {inline,escape,codeBlock}) {
  const index=Math.max(0,zeroSteps.findIndex((s,i)=>s.id===stepId||String(i+1)===stepId));
  const s=zeroSteps[index];
  const reviewParagraphs=s.id==='deps'?s.paragraphs.slice(0,-1):s.paragraphs;
  const projectBridge=s.id==='deps'?`<aside class="zero-goal"><b>${ui('回到 LoongSuite：','Back to LoongSuite:')}</b><p>${inline(s.paragraphs.at(-1).replace(/^回到 LoongSuite：|^Back to LoongSuite:\s*/,'').trim())}</p></aside>`:'';
  return `<div class="zero-layout"><header class="zero-header"><div class="eyebrow">${ui('从零开始 / 不需要先认识探针术语','Start here / no probe terminology required')}</div><h1>${ui('先理解为什么，','Understand why first,')}<br>${ui('再看代码怎么做。','then see how the code does it.')}</h1><p>${ui('从一次查房间开始：先看程序做了什么，再认代码里的词。图与代码用来解释过程；浏览器不会执行 Go。','Start with a room-checking function: see what the program does before naming the code concepts. Diagrams and code explain the process; the browser does not run Go.')}</p></header><nav class="zero-nav" aria-label="${ui('从零开始的七个步骤','Seven starter steps')}">${zeroSteps.map((x,i)=>`<a href="#/start/${i+1}" ${i===index?'aria-current="step" class="active"':''}><span>${String(i+1).padStart(2,'0')}</span>${escape(x.title)}</a>`).join('')}</nav><article class="zero-lesson"><div class="eyebrow">${ui('第','Step ')}${index+1} / ${zeroSteps.length} ${ui('步 ·','· ')}${escape(s.title)}</div><h2>${escape(s.question)}</h2><aside class="zero-goal"><p><b>${ui('这页学会一件事：','One thing to learn here:')}</b>${inline(s.goal)}</p><p><b>${ui('从这里接上：','Connect from here:')}</b>${inline(s.beforeYouRead)}</p></aside>${renderLessonDemo('zero',s.id)}${projectBridge}<details class="zero-review"><summary>${ui('需要文字复习？查看解释、术语和代码对照','Need a text review? Read the explanation, terms, and code comparison')}</summary><div>${reviewParagraphs.map(p=>`<p>${inline(p)}</p>`).join('')}<section class="zero-terms"><h3>${ui('刚出现的词，在这里解释','New terms explained here')}</h3>${termCards(s.terms,inline,escape)}</section><figure class="plain-figure">${plainFlow(s.flow,escape)}<figcaption>${ui('按箭头顺序理解；这是一张教学简图。','Follow the arrows; this is a teaching sketch.')}</figcaption></figure><section class="zero-example"><h3>${escape(s.before.label)}</h3>${codeBlock(s.before.code,s.before.language||'go')}<h3>${escape(s.after.label)}</h3>${codeBlock(s.after.code,s.after.language||'go')}<p class="example-caption">${inline(s.caption)}</p></section></div></details><section class="self-explain"><div class="eyebrow">${ui('停一下，用自己的话说','Pause and explain it in your own words')}</div><h3>${escape(s.check.question)}</h3><details><summary>${ui('展开参考解释','Show a reference explanation')}</summary><p>${inline(s.check.answer)}</p></details></section><aside class="takeaway"><b>${ui('这一步只带走一句话：','One sentence to take away:')}</b>${inline(s.takeaway)}</aside>${s.destination?`<p><a class="btn" href="${escape(s.destination.href)}">${escape(s.destination.label)}</a></p>`:''}<nav class="prev-next" aria-label="${ui('入门步骤切换','Starter step navigation')}">${index?`<a href="#/start/${index}"><small>← ${ui('上一步','Previous step')}</small>${escape(zeroSteps[index-1].title)}</a>`:`<a href="#/"><small>← ${ui('查看全景','View overview')}</small>${ui('回到学习路线','Back to learning path')}</a>`}${index<zeroSteps.length-1?`<a href="#/start/${index+2}"><small>${ui('下一步','Next step')} →</small>${escape(zeroSteps[index+1].title)}</a>`:`<a href="#/learn/orientation"><small>${ui('开始正式课程','Start the main course')} →</small>${ui('跟随一次构建读懂源码','Understand the source through one build')}</a>`}</nav><details class="zero-references"><summary>${ui('本组讲解的来源','Sources for this lesson')}</summary><ul>${zeroSources.map(s=>`<li><a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)} ↗</a></li>`).join('')}</ul></details></article></div>`;
}

const sourcePhases=[
  {label:ui('看清项目','See the project'),href:'go-mod',ids:['go-mod']},
  {label:ui('启动构建','Start the build'),href:'cli',ids:['cli']},
  {label:ui('准备依赖和规则','Prepare dependencies and rules'),href:'preprocess',ids:['preprocess','deps','rule-load','rule-model','bundle','rule-json']},
  {label:ui('接到编译工具','Connect to the compiler'),href:'toolexec',ids:['toolexec','match']},
  {label:ui('改写函数','Rewrite functions'),href:'instrument',ids:['instrument','func-ast','trampoline','call-context','call-context-impl','hook-rule']},
  {label:ui('运行并记录','Run and record'),href:'otel-runtime',ids:['linkname','gls','otel-runtime','version-boundary']}
];

export function renderSourcePage(s, lesson, nodes, {inline,escape,codeBlock}) {
  const phase=sourcePhases.find(p=>p.ids.includes(s.id));
  const l=lesson;
  return `<header class="source-intro"><div class="eyebrow">${ui('源码地图 / 先讲问题，再读实现','Source map / explain the problem before the implementation')}</div><h1>${escape(l.title)}</h1><p class="source-plain">${inline(l.plain)}</p><p><a class="btn light" href="#lesson-demo-source-${escape(s.id)}" data-scroll="lesson-demo-source-${escape(s.id)}">${ui('先看本页实例动画 ↓','See this page’s example animation ↓')}</a></p><p>${ui('第一次接触？','New to this?')} <a href="#/start/1">${ui('从一个普通 Go 函数开始 →','Start with an ordinary Go function →')}</a>${s.id==='deps'?`　${ui('也可先补','You can also review')} <a href="#/start/2">${ui('包和模块','packages and modules')}</a>、<a href="#/start/3">go.mod</a>、<a href="#/start/6">${ui('依赖为什么要补','why dependencies are added')}</a>。`:''}</p></header><nav class="source-journey" aria-label="${ui('这个文件在整个流程的哪里','Where this file fits in the overall flow')}">${sourcePhases.map((p,i)=>`<a href="#/source/${p.href}" class="${phase===p?'current':''}" ${phase===p?'aria-current="location"':''}><small>${i+1}</small>${escape(p.label)}</a>`).join('')}</nav><p class="diagram-caption">${ui('这是理解职责的顺序；“准备依赖和规则”内部会交替更新依赖与匹配，不是一条只走一次的直线。','This order explains responsibilities; “prepare dependencies and rules” alternates dependency updates and matching rather than running as one straight pass.')}</p><details class="source-index"><summary>${ui('切换源码节点 · 共','Switch source nodes ·')} ${nodes.length} ${ui('个 · 当前：','nodes · current:')}${escape(s.title)}</summary><div class="source-index-body"><label for="source-filter">${ui('按函数、文件或职责筛选','Filter by function, file, or responsibility')}</label><input class="filter-input" id="source-filter" type="search" placeholder="${ui('例如：依赖、addDependency、hook','e.g. dependency, addDependency, hook')}"><nav class="source-list" aria-label="${ui('源码阅读路径','Source reading path')}">${nodes.map((x,i)=>`<button class="source-item ${x.id===s.id?'active':''}" data-source="${escape(x.id)}" aria-pressed="${x.id===s.id}"><span class="num">${String(i+1).padStart(2,'0')}</span><span>${escape(x.title)}<small>${escape(x.path)}</small></span></button>`).join('')}</nav><p class="empty source-no-results" hidden>${ui('没有匹配节点；试试“依赖”、hook 或函数名。','No matching nodes; try “dependency”, hook, or a function name.')}</p></div></details><article class="source-detail source-lesson">${renderLessonDemo('source',s.id)}${s.id==='preprocess'?preprocessRealExample:''}<section class="why-box"><h2>${ui('先说为什么需要它','Why this is needed')}</h2><p>${inline(l.why)}</p></section><section class="source-section"><h2>01 · ${ui('本页先认这些词','Terms to know on this page')}</h2>${termCards(l.terms,inline,escape)}${l.prerequisites.length?`<p class="source-prerequisites">${ui('还不熟？','Need a refresher?')} ${l.prerequisites.map(p=>`<a href="${escape(p.href)}">${escape(p.label)} →</a>`).join('　')}</p>`:''}</section>${s.id==='deps'?`<figure class="plain-figure"><h3>${ui('别把这三个角色混在一起','Do not conflate these three roles')}</h3>${plainFlow([[ui('你的业务项目','Your application'),ui('被加工：原本负责处理请求','Transformed: originally handles requests')],[ui('otel 构建工具','otel build tool'),ui('加工者：准备依赖并改写编译输入','Transformer: prepares dependencies and rewrites compiler input')],[ui('hook 和记录库','hook and recording library'),ui('被接入业务产物：运行时真正记录','Connected to the application: records at runtime')]],escape)}<figcaption>${ui('工具能运行 ≠ 业务已经拥有它生成代码要用的库。第三个角色的代码也必须能被业务构建找到。','A tool running does not mean the application has the libraries its generated code needs. The third role’s code must also be discoverable by the application build.')}</figcaption></figure>`:''}<section class="source-section"><h2>02 · ${ui('它拿到什么，交出什么','What it receives and produces')}</h2><div class="io-pair"><section><span>${ui('输入','Input')}</span><p>${inline(l.input)}</p></section><section><span>${ui('输出 / 产生的变化','Output / resulting change')}</span><p>${inline(l.output)}</p></section></div></section><section class="source-section"><h2>03 · ${ui('用小例子拆开看','Break it down with a small example')}</h2><ol class="explain-steps">${l.steps.map((step,i)=>`<li><div class="step-marker">${i+1}</div><div><h3>${escape(step.title)}</h3><p>${inline(step.explanation)}</p>${step.code?codeBlock(step.code,step.language||'text'):''}</div></li>`).join('')}</ol></section><section class="source-section"><h2>04 · ${ui('再把人话对上源码','Map the plain-language explanation to source')}</h2><p class="source-path">${escape(s.path)}:${s.line} · ${escape(s.symbol)}</p><div class="source-annotations">${l.sourceNotes.map(n=>`<section><code>${escape(n.code)}</code><p>${inline(n.explanation)}</p></section>`).join('')}</div><details class="raw-source"><summary>${ui('我想看原始源码摘录（可稍后再读）','Show the raw source excerpt (you can read it later)')}</summary><p>${ui('摘录固定在','Excerpt pinned to')} v1.15.0 / <code>cac4009</code>；${ui('保留上游行号。片段会截断，完整函数请打开来源。','upstream line numbers are retained. The excerpt is shortened; open the source for the complete function.')}</p>${codeBlock(s.snippet||ui('请打开来源查看完整代码。','Open the source for the complete code.'),ui('Go · 上游行号','Go · upstream line numbers'),false)}<a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${ui('打开这个函数的固定提交源码 ↗','Open this function at the pinned source revision ↗')}</a></details></section><section class="source-section"><h2>05 · ${ui('容易混淆的地方','Common points of confusion')}</h2><ul class="pitfalls">${l.pitfalls.map(p=>`<li>${inline(p)}</li>`).join('')}</ul></section><section class="self-explain"><div class="eyebrow">${ui('不背定义，用因果解释','Explain the cause and effect, not a definition')}</div><h2>${escape(l.check.question)}</h2><details><summary>${ui('展开参考解释','Show a reference explanation')}</summary><p>${inline(l.check.answer)}</p></details></section><div class="toolbar"><a class="btn" href="${escape(l.next.href)}">${escape(l.next.label)} →</a><a class="btn light" href="#/start/1">${ui('回到从零开始','Back to Start here')}</a></div><p class="diagram-caption">${ui('源码摘录版权归上游作者，采用 Apache-2.0。讲解、简图与教学示例由本指南编写。','Source excerpts belong to their upstream authors under Apache-2.0. Explanations, diagrams, and teaching examples are written for this guide.')} <a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${ui('本页源码依据 ↗','Source basis for this page ↗')}</a></p></article>`;
}

const preprocessRealExample=`<aside class="source-real-example"><h3>${ui('源码里的同类情况：给 GORM 加观察代码，为什么会多出 MySQL 包？','A similar source case: why does adding observation to GORM add a MySQL package?')}</h3><p>${ui('假设业务原来使用匹配版本的 GORM 和 PostgreSQL，没有引用 MySQL driver。第一次匹配会选中 GORM 的','Suppose the application uses matching GORM and PostgreSQL versions without a MySQL driver. The first match selects GORM’s')} <code>Open</code> ${ui('规则。这个规则指向的','rule. That rule points to')} <code>pkg/rules/gorm/setup.go</code> ${ui('自己却引用了','which itself imports')} <code>gorm.io/driver/mysql</code>，${ui('并访问','and reads')} <code>Config.DbInfo</code>。</p><p>${ui('把 GORM 记录包加入构建以后，MySQL driver 也进入构建范围；第二次匹配才能对它应用“给 Config 增加 DbInfo 字段”的规则。这解释了为什么加入规则代码后还要重新匹配。第三次准备按最终结果再生成、同步；本例不保证第三次一定增加新模块。','After the GORM recording package enters the build, the MySQL driver is also in scope; only the second match can apply the rule that adds DbInfo to Config. That is why adding rule code requires matching again. The third preparation pass then generates and synchronizes from the final result; this example does not guarantee that a third pass adds a new module.')}</p><p>${ui('上面的动画用两个教学自定义规则，把“第二次匹配又选出一个带记录包的规则”的情形拆得更明显。实际依赖取决于你的项目；当前实现固定两次匹配，没有循环到完全不再变化的检查。','The animation uses two teaching-only custom rules to make the “second match selects another rule with a recording package” case clearer. Actual dependencies depend on your project; the current implementation performs two fixed matches and does not loop until stable.')}</p><p>${ui('这是基于固定源码推导的路径，没有在本页执行该数据库组合。对应源码：','This path is inferred from the pinned source; the database combination was not executed here. Sources:')} <a href="https://github.com/alibaba/loongsuite-go/blob/cac400935add57d8219122ba32857b8f55ac6eb1/tool/data/rules/gorm.json" target="_blank" rel="noopener noreferrer">GORM ${ui('规则','rules')}</a> · <a href="https://github.com/alibaba/loongsuite-go/blob/cac400935add57d8219122ba32857b8f55ac6eb1/pkg/rules/gorm/setup.go#L106" target="_blank" rel="noopener noreferrer">${ui('记录包读取 DbInfo','recording package reads DbInfo')}</a> · <a href="https://github.com/alibaba/loongsuite-go/blob/cac400935add57d8219122ba32857b8f55ac6eb1/tool/preprocess/preprocess.go#L273" target="_blank" rel="noopener noreferrer">${ui('三轮的实际控制流','actual three-pass control flow')}</a></p></aside>`;
